34	// ── Sm90 (Hopper) warp-group collective GEMM headers ──────────────────────
35	// The previous code used the default device::Gemm (no arch tag) which, with no arch
36	// tag, silently defaults to the SIMT/Sm70 path — i.e. NO tensor cores, NO
37	// WGMMA, NO TMA. To actually emit Hopper WGMMA/TMA instructions we build a
38	// GemmUniversalAdapter from the Sm90 CollectiveBuilder mainloop + collective
39	// epilogue. FP32 accumulate throughout (matches cuBLAS CUBLAS_COMPUTE_32F).
40	#include <cute/tensor.hpp>
41	#include <cutlass/gemm/device/gemm_universal_adapter.h>
42	#include <cutlass/gemm/collective/collective_builder.hpp>
43	#include <cutlass/gemm/kernel/gemm_universal.hpp>
44	#include <cutlass/epilogue/collective/collective_builder.hpp>
45	#include <cutlass/util/packed_stride.hpp>
