47	namespace sg { namespace sm90 { namespace mma {
48	
49	// ─────────────────────────────────────────────────────────────────────────
50	//  Sm90 collective GEMM (TMA + WGMMA, FP32 accumulate)
51	//
52	//  Generic builder parameterised on the input element type. Row-major A,
53	//  row-major B, row-major C with FP32 output. C = alpha*A*B + beta*C.
54	//
55	//  Why this exists: the old the default device::Gemm (no arch tag) instantiation
56	//  carried no arch tag and therefore compiled the SIMT (Sm70) kernel — no
57	//  tensor cores at all. GemmUniversalAdapter<GemmUniversal<...>> built from
58	//  CollectiveBuilder<arch::Sm90, OpClassTensorOp, ...> guarantees the Hopper
59	//  warp-group MMA + TMA path is emitted.
60	//
61	//  GemmUniversalAdapter requires a workspace; we query get_workspace_size()
62	//  and serve it from a per-thread cached device buffer (grown on demand).
63	// ─────────────────────────────────────────────────────────────────────────
64	
65	// Per-thread, lazily grown CUTLASS workspace. Avoids a cudaMalloc per call.
66	// Lifetime = process lifetime (intentional: the buffer is reused). Sized to
67	// the largest workspace any GEMM in this thread has requested so far.
68	inline void* sm90_get_workspace(size_t bytes) {
69	    static thread_local void*  ws_ptr   = nullptr;
70	    static thread_local size_t ws_bytes = 0;
71	    if (bytes > ws_bytes) {
72	        if (ws_ptr) cudaFree(ws_ptr);
73	        if (cudaMalloc(&ws_ptr, bytes) != cudaSuccess) {
74	            ws_ptr = nullptr;
75	            ws_bytes = 0;
76	            return nullptr;
77	        }
78	        ws_bytes = bytes;
79	    }
80	    return ws_ptr;
81	}
82	
83	// ─────────────────────────────────────────────────────────────────────────
84	//  §3.1 — TMA-descriptor / operator reuse (shape-keyed host cache)
85	//
86	//  WHAT IS REUSED (and WHY this is the correct CUTLASS-3.6 reuse):
87	//  ----------------------------------------------------------------
88	//  CUTLASS 3.6 builds the Hopper TMA tensor-map descriptors *inside*
89	//  `op.initialize(args, ws, stream)` → `GemmKernel::to_underlying_arguments`
90	//  → `CollectiveMainloop::to_underlying_arguments`, which calls
91	//  `make_tma_copy_A/B_sm90(...)` (sm90_mma_tma_gmma_ss_warpspecialized.hpp
92	//  lines 215-226). Those descriptors (one cuTensorMapEncode each for A and B,
93	//  plus the epilogue's C map) are baked into the operator's `params_` member.
94	//  GemmUniversalAdapter exposes `run(stream)` precisely "to re-launch the same
95	//  kernel without updating internal params" (gemm_universal_adapter.h:545) —
96	//  i.e. reusing the already-built descriptors.
97	//
98	//  So the supported, internals-respecting reuse is NOT to reach into CUTLASS's
99	//  TMA path, but to CACHE THE INITIALIZED OPERATOR keyed by everything its
100	//  descriptors encode, and on a recurring shape skip
101	//  make_cute_packed_stride + Arguments construction + get_workspace_size +
102	//  initialize (which is where the cuTensorMapEncode calls live) and just call
103	//  the cached `op.run(stream)`.
104	//
105	//  DESCRIPTOR ADDRESS-STABILITY (correctness invariant):
106	//  ----------------------------------------------------------------
107	//  A Hopper TMA tensor map encodes the *global base address* of the tensor
108	//  (make_tma_copy is fed `make_tensor(ptr_A, ...)`), the box/shape and the
109	//  strides. Therefore a cached operator is bit-for-bit equivalent to a freshly
110	//  rebuilt one IFF (M,N,K), the A/B/C base pointers, AND the strides all match.
111	//  Strides here are a pure function of (M,N,K) (row-major packed), so the key
112	//  is {M,N,K, A, B, C}. The optimizer/model buffers this serves (param/m/v
113	//  state, weights, and the grown-once FP32 scratch) are allocated ONCE and keep
114	//  the same address every step → stable key → cache hit. If any buffer is
115	//  reallocated to a new address, the key changes → MISS → rebuild, so a stale
116	//  descriptor can never be launched against a moved buffer (that would be wrong
117	//  results / an illegal access). This is the load-bearing safety property.
118	//
119	//  WORKSPACE LIFETIME:
120	//  ----------------------------------------------------------------
121	//  For this builder (1x1x1 cluster, kGemm, no split-K) the kernel reports
122	//  get_workspace_size()==0 and the adapter adds a barrier workspace only when
123	//  cute::size(ClusterShape)>1 — so the served GEMMs need no workspace and
124	//  `initialize` is called with ws==nullptr. We still query the size and, if a
125	//  future tile/cluster change makes it non-zero, each cache entry OWNS its own
126	//  workspace allocation (freed on eviction) so a cached operator's params can
127	//  never dangle into the shared grow-only `sm90_get_workspace` buffer.
128	//
129	//  EVICTION: fixed-size, direct-mapped (hash → slot). On collision the resident
130	//  entry is evicted (its owned workspace freed) and replaced — bounded memory,
131	//  no leak. Only a handful of distinct (shape,ptr) signatures recur per run, so
132	//  collisions are rare.
133	//
134	//  THREAD-SAFETY: the cache is `thread_local` (one instance per template
135	//  instantiation PER HOST THREAD). The launcher is single-threaded per stream
136	//  in this codebase, so each launching thread owns its own cache and no lock is
137	//  needed — the former std::mutex has been dropped. A thread_local cache is also
138	//  strictly correct for multi-thread launchers: each thread caches only the
139	//  operators it itself built, so there is no cross-thread sharing to race on.
140	//  (The cached device buffers / TMA descriptors are stream/context state, not
141	//  thread state, but each thread re-builds+initializes its own operator on a
142	//  miss, so correctness holds; the only cost of thread-local is that two threads
143	//  launching the same shape each pay one build.)
144	//
145	//  ELECT/MBARRIER BOUNDARY (honest note):
146	//  ----------------------------------------------------------------
147	//  §3.4's elect_one_sync()/Mbarrier (warp_specialize.cuh) compose a
148	//  HAND-WRITTEN producer/consumer TMA staging loop. The CUTLASS GEMM is a
149	//  self-contained kernel that OWNS its TMA mainloop — there is no hand-written
150	//  TMA staging in mma.cuh to inject a leader/barrier into. Pairing the elect/
151	//  mbarrier primitives with TMA therefore belongs to the Stage-6 megakernel's
152	//  hand-written TMA path, NOT here. Stage 4.1 is the host-side operator/
153	//  descriptor cache only.
154	// ─────────────────────────────────────────────────────────────────────────
155	
156	// Problem signature the cached descriptors depend on. Pointers are part of the
157	// key because a TMA tensor map encodes the global base address (see above).
158	struct GemmCacheKey {
159	    int         M, N, K;
160	    const void* A;
161	    const void* B;
162	    void*       C;
163	
164	    bool operator==(const GemmCacheKey& o) const {
165	        return M == o.M && N == o.N && K == o.K &&
166	               A == o.A && B == o.B && C == o.C;
167	    }
168	};
169	
170	inline uint64_t sm90_gemm_key_hash(const GemmCacheKey& k) {
171	    // FNV-1a over the raw key bytes — cheap, decent spread for the small set
172	    // of distinct signatures that recur.
173	    auto mix = [](uint64_t h, uint64_t v) {
174	        h ^= v; h *= 0x100000001b3ull; return h;
175	    };
176	    uint64_t h = 0xcbf29ce484222325ull;
177	    h = mix(h, (uint64_t)(uint32_t)k.M);
178	    h = mix(h, (uint64_t)(uint32_t)k.N);
179	    h = mix(h, (uint64_t)(uint32_t)k.K);
180	    h = mix(h, (uint64_t)k.A);
181	    h = mix(h, (uint64_t)k.B);
182	    h = mix(h, (uint64_t)k.C);
183	    return h;
184	}
185	
186	// Per-Gemm-instantiation, fixed-size, direct-mapped cache of INITIALIZED
187	// operators. Holds the operator (with its baked-in TMA descriptors / params_)
188	// and the workspace it was initialized with. The operator is stored by value;
189	// GemmUniversalAdapter is just a `Params params_` holder (copy/move-able) and
190	// is re-launched via op.run(stream), which reuses params_ unchanged.
191	template <typename Gemm>
192	struct Sm90GemmCache {
193	    static constexpr int kSlots = 16;   // bounded; covers the recurring shapes
194	
195	    struct Entry {
196	        bool         valid = false;
197	        GemmCacheKey key{};
198	        Gemm         op{};
199	        void*        ws       = nullptr;   // OWNED by this entry (may be null)
200	        size_t       ws_bytes = 0;
201	    };
202	
203	    Entry slots[kSlots];
204	
205	    static Sm90GemmCache& instance() {
206	        // thread_local: each host thread owns its cache → no lock needed (the
207	        // launcher is single-thread per stream). Keyed by {M,N,K,A,B,C} so a
208	        // moved buffer changes the key → MISS → rebuild (no stale TMA descriptor
209	        // ever launched against a relocated buffer — the load-bearing invariant).
210	        static thread_local Sm90GemmCache c;
211	        return c;
212	    }
213	};
214	
215	template <typename Gemm>
216	inline int sm90_gemm_slot(const GemmCacheKey& k) {
217	    return (int)(sm90_gemm_key_hash(k) & (uint64_t)(Sm90GemmCache<Gemm>::kSlots - 1));
218	}
219	
220	// Build a row-major-packed Arguments for (M,N,K) with the given A/B/C and run
221	// it, caching the initialized operator so a recurring (shape,ptr) signature
222	// skips make_stride + Arguments + initialize (and thus the cuTensorMapEncode
223	// calls) and re-launches the cached op directly.
224	template <typename Gemm, typename ElementA, typename ElementB, typename ElementAcc>
225	inline cudaError_t sm90_run_gemm_cached(
226	    int M, int N, int K,
227	    const void* A, const void* B, float* C,
228	    cudaStream_t stream)
229	{
230	    using StrideA = typename Gemm::GemmKernel::StrideA;
231	    using StrideB = typename Gemm::GemmKernel::StrideB;
232	    using StrideC = typename Gemm::GemmKernel::StrideC;
233	
234	    GemmCacheKey key{M, N, K, A, B, C};
235	    auto& cache = Sm90GemmCache<Gemm>::instance();
236	    int   slot  = sm90_gemm_slot<Gemm>(key);
237	
238	    // No lock: the cache is thread_local (single-thread per stream launcher).
239	    auto& e = cache.slots[slot];
240	
241	    // HIT: identical (shape,ptr) signature → cached descriptors are valid.
242	    if (e.valid && e.key == key) {
243	        cutlass::Status st = e.op.run(stream);
244	        return (st == cutlass::Status::kSuccess) ? cudaSuccess : cudaErrorUnknown;
245	    }
246	
247	    // MISS (empty or colliding signature): build + initialize a fresh operator.
248	    StrideA stride_a = cutlass::make_cute_packed_stride(StrideA{}, {M, K, 1});
249	    StrideB stride_b = cutlass::make_cute_packed_stride(StrideB{}, {N, K, 1});
250	    StrideC stride_c = cutlass::make_cute_packed_stride(StrideC{}, {M, N, 1});
251	
252	    typename Gemm::Arguments args{
253	        cutlass::gemm::GemmUniversalMode::kGemm,
254	        {M, N, K, 1},
255	        { reinterpret_cast<const ElementA*>(A), stride_a,
256	          reinterpret_cast<const ElementB*>(B), stride_b },
257	        { {ElementAcc(1.0f), ElementAcc(0.0f)},
258	          C, stride_c, C, stride_c }
259	    };
260	
261	    Gemm op;
262	    cutlass::Status st = op.can_implement(args);
263	    if (st != cutlass::Status::kSuccess) return cudaErrorNotSupported;
264	
265	    size_t ws_size = Gemm::get_workspace_size(args);
266	
267	    // Evict the resident colliding entry (free its OWNED workspace) before reuse.
268	    if (e.valid && e.ws) {
269	        cudaFree(e.ws);
270	        e.ws = nullptr;
271	        e.ws_bytes = 0;
272	    }
273	
274	    void* ws = nullptr;
275	    if (ws_size > 0) {
276	        // Entry owns its workspace so the cached operator's params can never
277	        // dangle into the shared grow-only buffer.
278	        if (cudaMalloc(&ws, ws_size) != cudaSuccess) {
279	            e.valid = false;
280	            return cudaErrorMemoryAllocation;
281	        }
282	    }
283	
284	    st = op.initialize(args, ws, stream);
285	    if (st != cutlass::Status::kSuccess) {
286	        if (ws) cudaFree(ws);
287	        e.valid = false;
288	        return cudaErrorUnknown;
289	    }
290	
291	    st = op.run(stream);
292	    if (st != cutlass::Status::kSuccess) {
293	        if (ws) cudaFree(ws);
294	        e.valid = false;
295	        return cudaErrorUnknown;
296	    }
297	
298	    // Install into the cache for subsequent recurring invocations.
299	    e.op       = op;          // copies params_ (baked TMA descriptors)
300	    e.key      = key;
301	    e.ws       = ws;
302	    e.ws_bytes = ws_size;
303	    e.valid    = true;
304	    return cudaSuccess;
305	}
