533	// Run a single C[MxN] = A[MxK] · op(B) with FP32 accumulate on the Sm90
534	// collective. op(B) is B (LayoutBT=RowMajor) or Bᵀ (LayoutBT=ColumnMajor).
535	template <typename ElementInput, typename LayoutBT>
536	inline cudaError_t sm90_run_gemm_bt(
537	    int M, int N, int K,
538	    const void* A, const void* B, float* C,
539	    cudaStream_t stream)
540	{
541	    using G          = Sm90GemmBT<ElementInput, LayoutBT>;
542	    using Gemm       = typename G::Gemm;
543	    using ElementA   = typename G::ElementA;
544	    using ElementB   = typename G::ElementB;
545	    using ElementAcc = typename G::ElementAcc;
546	
547	    // §3.1: same shape-keyed operator cache as sm90_run_gemm. The cache is
548	    // per-Gemm-instantiation, so each (ElementInput, LayoutBT) flavour gets its
549	    // own slot table — a RowMajor-B descriptor is never confused with a
550	    // ColumnMajor-B (Bᵀ) one even at identical (M,N,K,ptrs).
551	    return sm90_run_gemm_cached<Gemm, ElementA, ElementB, ElementAcc>(
552	        M, N, K, A, B, C, stream);
553	}
