555	// ─────────────────────────────────────────────────────────────────────────
556	//  §5/§7 — Templated-OUTPUT Sm90 collective GEMM (TMA + WGMMA, FP32 accum)
557	//
558	//  Same builder as Sm90GemmBT but ElementC = ElementOut (the activation dtype:
559	//  half/bf16, or float for the TF32 path). The collective epilogue casts the
560	//  FP32 accumulator straight into the ElementOut C buffer, so a half/bf16 GEMM
561	//  no longer needs an FP32 scratch buffer + a separate cast kernel — it writes
562	//  the typed result directly. FP32 accumulate throughout (unchanged numerics
563	//  vs the float-scratch-then-cast path; the cast happens in the epilogue
564	//  instead of a follow-up kernel, with the same round-to-nearest).
565	//
566	//  This is an ADDITIVE capability: the existing float-output Sm90GemmBT /
567	//  sm90_run_gemm_bt path is KEPT as the default so nothing breaks. Callers that
568	//  want to skip the scratch+cast can opt into sm90_run_gemm_bt_out.
569	//  Verified to compile for {half→half, bf16→bf16, tf32→float}.
570	// ─────────────────────────────────────────────────────────────────────────
571	template <typename ElementInput, typename ElementOut, typename LayoutBT>
572	struct Sm90GemmBTOut {
573	    using ElementA   = ElementInput;
574	    using ElementB   = ElementInput;
575	    using ElementC   = ElementOut;     // typed output (no FP32 scratch + cast)
576	    using ElementAcc = float;          // FP32 accumulate
577	    using LayoutA    = cutlass::layout::RowMajor;
578	    using LayoutB    = LayoutBT;
579	    using LayoutC    = cutlass::layout::RowMajor;
580	
581	    static constexpr int AlignA = 128 / cutlass::sizeof_bits<ElementA>::value;
582	    static constexpr int AlignB = 128 / cutlass::sizeof_bits<ElementB>::value;
583	    static constexpr int AlignC = 128 / cutlass::sizeof_bits<ElementC>::value;
584	
585	    using TileShape    = cute::Shape<cute::_128, cute::_128, cute::_64>;
586	    using ClusterShape = cute::Shape<cute::_1, cute::_1, cute::_1>;
587	
588	    using CollectiveEpilogue =
589	        typename cutlass::epilogue::collective::CollectiveBuilder<
590	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
591	            TileShape, ClusterShape,
592	            cutlass::epilogue::collective::EpilogueTileAuto,
593	            ElementAcc, ElementAcc,
594	            ElementC, LayoutC, AlignC,
595	            ElementC, LayoutC, AlignC,
596	            cutlass::epilogue::collective::EpilogueScheduleAuto
597	        >::CollectiveOp;
598	
599	    using CollectiveMainloop =
600	        typename cutlass::gemm::collective::CollectiveBuilder<
601	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
602	            ElementA, LayoutA, AlignA,
603	            ElementB, LayoutB, AlignB,
604	            ElementAcc,
605	            TileShape, ClusterShape,
606	            cutlass::gemm::collective::StageCountAutoCarveout<
607	                static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
608	            cutlass::gemm::collective::KernelScheduleAuto
609	        >::CollectiveOp;
610	
611	    using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
612	        cute::Shape<int, int, int, int>,
613	        CollectiveMainloop,
614	        CollectiveEpilogue>;
615	
616	    using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;
617	};
