619	// Run C[MxN] (ElementOut) = A[MxK] · op(B), FP32 accumulate, typed output.
620	// op(B) is B (LayoutBT=RowMajor) or Bᵀ (LayoutBT=ColumnMajor). Writes directly
621	// into the ElementOut buffer — no FP32 scratch, no separate cast kernel.
622	template <typename ElementInput, typename ElementOut, typename LayoutBT>
623	inline cudaError_t sm90_run_gemm_bt_out(
624	    int M, int N, int K,
625	    const void* A, const void* B, ElementOut* C,
626	    cudaStream_t stream)
627	{
