706	inline cudaError_t sm90_run_gemm_atb(
707	    int M, int N, int K,
708	    const void* A, const void* B, float* C,
709	    cudaStream_t stream)
710	{
711	    using G          = Sm90GemmAT<ElementInput>;
712	    using Gemm       = typename G::Gemm;
713	    using ElementA   = typename G::ElementA;
714	    using ElementB   = typename G::ElementB;
715	    using ElementAcc = typename G::ElementAcc;
