764	// ─────────────────────────────────────────────────────────────────────────
765	//  TF32 (tfloat32_t) tensor-core GEMM — the FP32 tensor-core path (LIVE).
766	//
767	//  FP32 inputs (plain `float` buffers) are fed to the Sm90 WGMMA mainloop with
768	//  ElementA/B = cutlass::tfloat32_t. tfloat32_t is a 4-byte type that occupies
769	//  the SAME storage as `float`; the WGMMA hardware rounds each operand's
770	//  mantissa to TF32's 10 explicit bits at MMA-issue time, accumulating in FP32.
771	//  So a `const float*` is reinterpret_cast to `const tfloat32_t*` (standard
772	//  CUTLASS idiom — no separate conversion buffer needed) and the result lands
773	//  in an FP32 C buffer, matching the FP32 output of the cuBLAS/scalar path.
774	//
775	//  PRECISION NOTE (🟡 numeric parity vs scalar FP32): TF32 carries a 10-bit
776	//  mantissa vs FP32's 23. This is the accepted, expected tensor-core "FP32"
777	//  mode (same precision class as cuBLAS CUBLAS_TF32_TENSOR_OP_MATH and
778	//  PyTorch's allow_tf32), NOT bit-identical to a scalar FP32 triple-loop. It is
779	//  an accuracy/precision tradeoff, not a bug. Callers demanding exact FP32 must
780	//  force the scalar path (the models gate this via SG_FORCE_SCALAR_FP32).
781	//
782	//  ALIGNMENT: tfloat32_t is 32-bit, so 128-bit vector access = 4 elements
783	//  (AlignA/B = 128/32). The Sm90 TF32 MMA atom (SM90_MMA_TF32) is selected
784	//  automatically by CollectiveBuilder<arch::Sm90, OpClassTensorOp, tfloat32_t,
785	//  ...>. Tile/cluster shapes are the same proven 128x128x64 / 1x1x1 used by the
786	//  half/bf16 builders above.
787	// ─────────────────────────────────────────────────────────────────────────
788	
789	// Run a single row-major C = A*B with FP32 (TF32 MMA) accumulate. A/B/C are
790	// plain float buffers; A and B are reinterpreted as tfloat32_t for the WGMMA.
791	inline cudaError_t sm90_run_gemm_tf32(
792	    int M, int N, int K,
793	    const float* A, const float* B, float* C,
794	    cudaStream_t stream)
795	{
796	    using G          = Sm90Gemm<cutlass::tfloat32_t>;
797	    using Gemm       = typename G::Gemm;
798	    using ElementAcc = typename G::ElementAcc;
799	    return sm90_run_gemm_cached<Gemm, cutlass::tfloat32_t, cutlass::tfloat32_t,
800	                                ElementAcc>(
801	        M, N, K, reinterpret_cast<const void*>(A),
802	        reinterpret_cast<const void*>(B), C, stream);
803	}
