109	// =========================================================================
110	//  Warp-level sum reduction (butterfly via __shfl_down_sync)
111	// =========================================================================
112	
113	__device__ __forceinline__ float warp_reduce_sum_f32(float v) {
114	    for (int offset = 16; offset > 0; offset >>= 1) {
115	        v += __shfl_down_sync(0xffffffff, v, offset);
116	    }
117	    return v;
118	}
119	
120	// =========================================================================
121	//  Block-level sum reduction: warp reduce + shared-memory tree + warp reduce.
122	//  Uses up to 32 floats of smem (one per warp).
123	// =========================================================================
124	
125	__device__ __forceinline__ float block_reduce_sum_f32(float v) {
126	    __shared__ float smem[32];
127	    const int tid = threadIdx.x;
128	    const int warp = tid / 32;
129	    const int lane = tid & 31;
130	
131	    float w = warp_reduce_sum_f32(v);
132	    if (lane == 0) smem[warp] = w;
133	    __syncthreads();
134	
135	    int n_warps = (blockDim.x + 31) / 32;
136	    if (warp == 0) {
137	        float x = (lane < n_warps) ? smem[lane] : 0.0f;
138	        x = warp_reduce_sum_f32(x);
139	        if (lane == 0) smem[0] = x;
140	    }
141	    __syncthreads();
142	    return smem[0];
143	}
144	
145	// =========================================================================
146	//  Block-level sum reduction of TWO floats in one pass (shared warp-tree).
147	//  Reduces a and b together: one shared-memory tile (2 floats/warp) and a
148	//  single pair of __syncthreads, instead of two back-to-back
149	//  block_reduce_sum_f32 calls (which serialize on the same static smem).
150	//  Used by the prodigy (r, s) reduce. Every thread returns the block sums.
151	// =========================================================================
152	
153	__device__ __forceinline__ void block_reduce_sum2_f32(
154	    float a, float b, float& a_out, float& b_out
155	) {
156	    __shared__ float smem_a[32];
157	    __shared__ float smem_b[32];
158	    const int tid = threadIdx.x;
159	    const int warp = tid / 32;
160	    const int lane = tid & 31;
161	
162	    a = warp_reduce_sum_f32(a);
163	    b = warp_reduce_sum_f32(b);
164	    if (lane == 0) { smem_a[warp] = a; smem_b[warp] = b; }
165	    __syncthreads();
166	
167	    const int n_warps = (blockDim.x + 31) / 32;
168	    if (warp == 0) {
169	        float xa = (lane < n_warps) ? smem_a[lane] : 0.0f;
170	        float xb = (lane < n_warps) ? smem_b[lane] : 0.0f;
171	        xa = warp_reduce_sum_f32(xa);
172	        xb = warp_reduce_sum_f32(xb);
173	        if (lane == 0) { smem_a[0] = xa; smem_b[0] = xb; }
174	    }
175	    __syncthreads();
176	    a_out = smem_a[0];
177	    b_out = smem_b[0];
178	}
