278	// Non-temporal (streaming) 16B store — bypasses L2 for write-once output.
279	__device__ __forceinline__ void stream_store_f32v4(float4* ptr, float4 v) {
280	    __stwt(reinterpret_cast<float*>(ptr) + 0, v.x);
281	    __stwt(reinterpret_cast<float*>(ptr) + 1, v.y);
282	    __stwt(reinterpret_cast<float*>(ptr) + 2, v.z);
283	    __stwt(reinterpret_cast<float*>(ptr) + 3, v.w);
284	}
