315	      int thread_idx,
316	      uint32_t block_rank_in_cluster,
317	      TensorStorage& shared_tensors) {
318	    int lane_predicate = cute::elect_one_sync();
319	
320	    if (lane_predicate) {
321	      Tensor sA = make_tensor(make_smem_ptr(shared_tensors.smem_A.data()), SmemLayoutA{});        // (BLK_M,BLK_K,PIPE)
322	      Tensor sB = make_tensor(make_smem_ptr(shared_tensors.smem_B.data()), SmemLayoutB{});        // (BLK_N,BLK_K,PIPE)
323	
324	      //
325	      // Prepare the TMA loads for A and B
326	      //
327	
328	      constexpr uint32_t cluster_shape_x = get<0>(typename DispatchPolicy::ClusterShape());
329	      uint2 cluster_local_block_id = {block_rank_in_cluster % cluster_shape_x, block_rank_in_cluster / cluster_shape_x};
330	
331	      Tensor gA_mkl = get<0>(load_inputs);
332	      Tensor gB_nkl = get<1>(load_inputs);
333	
334	      auto block_tma_a = mainloop_params.tma_load_a.get_slice(cluster_local_block_id.y);
335	      auto block_tma_b = mainloop_params.tma_load_b.get_slice(cluster_local_block_id.x);
336	
337	      // Partition the inputs based on the current block coordinates.
338	      auto [m_coord, n_coord, k_coord, l_coord] = blk_coord;
339	      Tensor gA = gA_mkl(_,_,m_coord,_,l_coord);                                                     // (BLK_M,BLK_K,k)
340	      Tensor gB = gB_nkl(_,_,n_coord,_,l_coord);                                                     // (BLK_N,BLK_K,k)
341	
342	      // Applies the mapping from block_tma_a
343	      Tensor tAgA = block_tma_a.partition_S(gA);                                                 // (TMA,TMA_M,TMA_K,k)
344	      Tensor tAsA = block_tma_a.partition_D(sA);                                              // (TMA,TMA_M,TMA_K,PIPE)
345	
346	      Tensor tBgB = block_tma_b.partition_S(gB);                                                 // (TMA,TMA_N,TMA_K,k)
347	      Tensor tBsB = block_tma_b.partition_D(sB);                                              // (TMA,TMA_N,TMA_K,PIPE)
348	
349	      uint16_t mcast_mask_a = 0;
350	      uint16_t mcast_mask_b = 0;
351	
352	      // Issue TmaLoads
353	      // Maps the tile -> block, value
354	      if constexpr (cute::is_same_v<GmemTiledCopyA, SM90_TMA_LOAD_MULTICAST>) {
355	        auto block_layout = Layout<typename DispatchPolicy::ClusterShape>{}; // (m,n) -> block_id
356	        for (int n = 0; n < size<1>(block_layout); ++n) {
357	          mcast_mask_a |= (uint16_t(1) << block_layout(cluster_local_block_id.x,n,Int<0>{}));
358	        }
359	      }
360	
361	      if constexpr (cute::is_same_v<GmemTiledCopyB, SM90_TMA_LOAD_MULTICAST>) {
362	        auto block_layout = Layout<typename DispatchPolicy::ClusterShape>{}; // (m,n) -> block_id
363	        for (int m = 0; m < size<0>(block_layout); ++m) {
364	          mcast_mask_b |= (uint16_t(1) << block_layout(m,cluster_local_block_id.y,Int<0>{}));
365	        }
366	      }
367	
368	      // Mainloop
369	      CUTLASS_PRAGMA_NO_UNROLL
370	      for ( ; k_tile_count > 0; --k_tile_count) {
371	        // LOCK smem_pipe_write for _writing_
372	        pipeline.producer_acquire(smem_pipe_write);
373	
374	        //
375	        // Copy gmem to smem for *k_tile_iter
376	        //
377	
378	        using BarrierType = typename MainloopPipeline::ProducerBarrierType;
379	        BarrierType* tma_barrier = pipeline.producer_get_barrier(smem_pipe_write);
380	
381	        int write_stage = smem_pipe_write.index();
382	        copy(mainloop_params.tma_load_a.with(*tma_barrier, mcast_mask_a), tAgA(_,_,_,*k_tile_iter), tAsA(_,_,_,write_stage));
383	        copy(mainloop_params.tma_load_b.with(*tma_barrier, mcast_mask_b), tBgB(_,_,_,*k_tile_iter), tBsB(_,_,_,write_stage));
384	        ++k_tile_iter;
385	
386	        // Advance smem_pipe_write
387	        ++smem_pipe_write;
388	      }
389	    }
390	  }
